namespace Compliance.Domain.RuleEngine
{
    public class RuleDefinitionCatalog
    {
        // Percentage Limit Rules
        public static RuleDefinition IssuerExposureLimit => new()
        {
            Type = RuleType.PercentageLimit,
            Category = RuleCategory.Issuer,
            Name = "Max Issuer Exposure",
            Expression = @"
                var currentExposure = portfolio.GetIssuerExposure(security.IssuerId);
                var proposedExposure = currentExposure + trade.Amount;
                var limit = fund.NAV * (parameters.MaxPercentage / 100m);
                return proposedExposure <= limit;
            ",
            ParameterSchema = new Dictionary<string, Type>
            {
                { "MaxPercentage", typeof(decimal) }
            },
            CapacityCalculation = @"
                var currentExposure = portfolio.GetIssuerExposure(security.IssuerId);
                var limit = fund.NAV * (parameters.MaxPercentage / 100m);
                return Math.Max(0, limit - currentExposure);
            "
        };

        public static RuleDefinition SecurityTypeRestriction => new()
        {
            Type = RuleType.SecurityTypeRestriction,
            Category = RuleCategory.Security,
            Name = "Security Type Whitelist",
            Expression = @"
                var allowedTypes = parameters.AllowedTypes
                    .Split(',')
                    .Select(t => t.Trim())
                    .ToList();
                return allowedTypes.Contains(security.Type);
            ",
            ParameterSchema = new Dictionary<string, Type>
