                { "AllowedTypes", typeof(string) }  // CSV: "TBill,Corporate"
            },
            CapacityCalculation = @"
                var allowedTypes = parameters.AllowedTypes
                    .Split(',')
                    .Select(t => t.Trim())
                    .ToList();
                return allowedTypes.Contains(security.Type) 
                    ? decimal.MaxValue 
                    : 0m;
            "
        };

        public static RuleDefinition CreditRatingRequirement => new()
        {
            Type = RuleType.RatingRequirement,
            Category = RuleCategory.Rating,
            Name = "Minimum Credit Rating",
            Expression = @"
                var ratingOrder = new[] { ""AAA"", ""AA+"", ""AA"", ""AA-"", 
                    ""A+"", ""A"", ""A-"", ""BBB+"", ""BBB"", ""BBB-"", 
                    ""BB+"", ""BB"", ""BB-"", ""B+"", ""B"", ""B-"" };
                var minIndex = Array.IndexOf(ratingOrder, parameters.MinRating);
                var securityIndex = Array.IndexOf(ratingOrder, security.CreditRating);
                return securityIndex >= 0 && securityIndex <= minIndex;
            ",
            ParameterSchema = new Dictionary<string, Type>
            {
                { "MinRating", typeof(string) }
            },
            CapacityCalculation = @"
                var ratingOrder = new[] { ""AAA"", ""AA+"", ""AA"", ""AA-"", 
                    ""A+"", ""A"", ""A-"", ""BBB+"", ""BBB"", ""BBB-"", 
                    ""BB+"", ""BB"", ""BB-"", ""B+"", ""B"", ""B-"" };
                var minIndex = Array.IndexOf(ratingOrder, parameters.MinRating);
                var securityIndex = Array.IndexOf(ratingOrder, security.CreditRating);
                var meetsRating = securityIndex >= 0 && securityIndex <= minIndex;
                return meetsRating ? decimal.MaxValue : 0m;
            "
        };

