### 4.2 Rule Evaluation Engine Design

```csharp
// Compliance.Domain/RuleEngine/RuleEvaluator.cs
namespace Compliance.Domain.RuleEngine
{
    public interface IRuleEvaluator
    {
        Task<RuleEvaluationResult> EvaluateAsync(
            ComplianceRule rule,
            RuleContext context);

        Task<decimal> CalculateCapacityAsync(
            ComplianceRule rule,
            RuleContext context);
    }

    public class RuleEvaluator : IRuleEvaluator
    {
        private readonly IScriptEngine _scriptEngine;
        private readonly ILogger<RuleEvaluator> _logger;

        public async Task<RuleEvaluationResult> EvaluateAsync(
            ComplianceRule rule,
            RuleContext context)
        {
            try
            {
                var globals = CreateGlobals(context);
                var expression = rule.Configuration.Expression;

                var result = await _scriptEngine.EvaluateAsync<bool>(
                    expression, 
                    globals);

                var capacity = result 
                    ? await CalculateCapacityAsync(rule, context)
                    : 0m;

                return new RuleEvaluationResult(
                    rule.Id.ToString(),
                    rule.Name,
                    result,
                    GetMessage(rule, context, result),
                    capacity,
                    GetThreshold(rule, context)
                );
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, 
                    "Rule evaluation failed for rule {RuleId}", 
                    rule.Id);
                throw new RuleEvaluationException(rule.Id, ex);
            }
        }

        public async Task<decimal> CalculateCapacityAsync(
            ComplianceRule rule,
            RuleContext context)
        {
            var globals = CreateGlobals(context);
            var capacityExpression = GetCapacityExpression(rule);

            var capacity = await _scriptEngine.EvaluateAsync<decimal>(
                capacityExpression, 
                globals);

            return Math.Max(0, capacity);
        }

        private Dictionary<string, object> CreateGlobals(RuleContext context)
        {
            return new Dictionary<string, object>
            {
                { "fund", context.Fund },
                { "security", context.Security },
                { "trade", context.Trade },
                { "portfolio", context.Portfolio },
                { "parameters", context.Rule.Configuration.Parameters }
            };
        }
    }

    // Using Roslyn C# Script API
    public interface IScriptEngine
    {
        Task<T> EvaluateAsync<T>(string expression, Dictionary<string, object> globals);
    }

    public class RoslynScriptEngine : IScriptEngine
    {
        private readonly ConcurrentDictionary<string, Script> _compiledScripts;

        public RoslynScriptEngine()
        {
            _compiledScripts = new ConcurrentDictionary<string, Script>();
        }

        public async Task<T> EvaluateAsync<T>(
            string expression, 
            Dictionary<string, object> globals)
        {
            var script = _compiledScripts.GetOrAdd(expression, expr =>
            {
                var options = ScriptOptions.Default
                    .AddReferences(typeof(Fund).Assembly)
                    .AddImports("System", "System.Linq", "System.Collections.Generic");

                return CSharpScript.Create<T>(expr, options, typeof(Globals));
            });

            var globalsObject = new Globals(globals);
            var result = await script.RunAsync(globalsObject);
            return result.ReturnValue;
        }
    }

    public class Globals
    {
        public Fund fund { get; set; }
        public Security security { get; set; }
        public TradeContext trade { get; set; }
        public Portfolio portfolio { get; set; }
        public Dictionary<string, object> parameters { get; set; }

        public Globals(Dictionary<string, object> values)
        {
            fund = (Fund)values["fund"];
            security = (Security)values["security"];
            trade = (TradeContext)values["trade"];
            portfolio = (Portfolio)values["portfolio"];
            parameters = (Dictionary<string, object>)values["parameters"];
        }
    }

    public record RuleContext(
        Fund Fund,
        Security Security,
        TradeContext Trade,
        Portfolio Portfolio,
        ComplianceRule Rule
    );

    public record TradeContext(
        decimal Amount,
        decimal Price,
        DateTime TradeDate,
        string CounterpartyId
    );

    public class Portfolio
    {
        private readonly IPortfolioRepository _repository;
        private readonly string _fundId;

        public decimal GetIssuerExposure(string issuerId)
        {
            return _repository.GetIssuerExposureAsync(_fundId, issuerId)
                .GetAwaiter()
                .GetResult();
        }

        public decimal GetSecurityPosition(string securityId)
        {
            return _repository.GetSecurityPositionAsync(_fundId, securityId)
                .GetAwaiter()
                .GetResult();
        }

        public decimal GetSectorExposure(string sector)
        {
            return _repository.GetSectorExposureAsync(_fundId, sector)
                .GetAwaiter()
                .GetResult();
        }
    }
}
