## 5. Allocation Engine

### 5.1 Pro-Rata Allocation Algorithm

```csharp
// Allocation.Services/Strategies/ProRataAllocationStrategy.cs
namespace Allocation.Services.Strategies
{
    public interface IAllocationStrategy
    {
        AllocationResponse Allocate(AllocationRequest request);
    }

    public class ProRataAllocationStrategy : IAllocationStrategy
    {
        public AllocationResponse Allocate(AllocationRequest request)
        {
            var totalCapacity = request.Funds.Sum(f => f.AvailableCapacity);

            if (totalCapacity <= 0)
            {
                return AllocationResponse.NoCapacity(request.RequestId);
            }

            var allocations = new List<FundAllocation>();
            var totalAllocated = 0m;

            // Calculate proportional allocations
            foreach (var fund in request.Funds)
            {
                var proportion = fund.AvailableCapacity / totalCapacity;
                var desiredAmount = request.TotalAmount * proportion;
                var allocatedAmount = Math.Min(
                    desiredAmount, 
                    fund.AvailableCapacity);

                allocations.Add(new FundAllocation(
                    fund.FundId,
                    allocatedAmount,
                    allocatedAmount / request.Price,
                    (allocatedAmount / request.TotalAmount) * 100m,
                    AllocationStatus.Allocated,
                    null
                ));

                totalAllocated += allocatedAmount;
            }

            // Handle rounding adjustments
            if (totalAllocated < request.TotalAmount)
            {
                var shortage = request.TotalAmount - totalAllocated;

                // Allocate remaining to fund with most capacity
                var fundWithMostRoom = allocations
                    .OrderByDescending(a => 
                        request.Funds.First(f => f.FundId == a.FundId)
                            .AvailableCapacity - a.AllocatedAmount)
                    .First();

                var updatedAllocation = fundWithMostRoom with
                {
                    AllocatedAmount = fundWithMostRoom.AllocatedAmount + shortage,
                    AllocatedShares = (fundWithMostRoom.AllocatedAmount + shortage) 
                        / request.Price,
                    PercentageOfTotal = ((fundWithMostRoom.AllocatedAmount + shortage) 
                        / request.TotalAmount) * 100m
                };

                allocations[allocations.IndexOf(fundWithMostRoom)] = 
                    updatedAllocation;
                totalAllocated += shortage;
            }

            var summary = new AllocationSummary(
                request.TotalAmount,
                totalAllocated,
                request.TotalAmount - totalAllocated,
                totalAllocated == request.TotalAmount,
                new List<string>()
            );

            return new AllocationResponse(
                request.RequestId,
                allocations,
                summary
            );
        }
    }
}
