```csharp
// Allocation.Services/AllocationService.cs
namespace Allocation.Services
{
    public interface IAllocationService
    {
        Task<AllocationResponse> AllocateAsync(AllocationRequest request);
    }

    public class AllocationService : IAllocationService
    {
        private readonly IAllocationStrategyFactory _strategyFactory;
        private readonly IAllocationRepository _repository;
        private readonly ILogger<AllocationService> _logger;

        public async Task<AllocationResponse> AllocateAsync(
            AllocationRequest request)
        {
            _logger.LogInformation(
                "Starting allocation for request {RequestId} using {Methodology}",
                request.RequestId,
                request.Methodology);

            var strategy = _strategyFactory.GetStrategy(request.Methodology);
            var response = strategy.Allocate(request);

            // Persist allocation result
            await _repository.SaveAllocationAsync(
                request.RequestId,
                response);

            _logger.LogInformation(
                "Allocation completed: {TotalAllocated} of {TotalRequested}",
                response.Summary.TotalAllocated,
                response.Summary.TotalRequested);

            return response;
        }
    }

    public interface IAllocationStrategyFactory
    {
        IAllocationStrategy GetStrategy(AllocationMethodology methodology);
    }

    public class AllocationStrategyFactory : IAllocationStrategyFactory
    {
        private readonly IServiceProvider _serviceProvider;

        public IAllocationStrategy GetStrategy(AllocationMethodology methodology)
        {
            return methodology switch
            {
                AllocationMethodology.ProRata => 
                    _serviceProvider.GetRequiredService<ProRataAllocationStrategy>(),
                AllocationMethodology.Targeted => 
                    _serviceProvider.GetRequiredService<TargetedAllocationStrategy>(),
                AllocationMethodology.Custom => 
                    _serviceProvider.GetRequiredService<CustomAllocationStrategy>(),
                _ => throw new NotSupportedException(
                    $"Methodology {methodology} not supported")
            };
        }
    }
