## 7. Orchestration Flow with Rollback

### 7.1 Detailed Workflow

```csharp
// TradeOrchestrator.API/Services/OrchestrationWorkflow.cs
public class OrchestrationWorkflow
{
    /*
    Workflow Steps:

    1. INITIATION
       - Receive trade submission
       - Generate request ID
       - Create orchestration state
       - Validate input

    2. COMPLIANCE EVALUATION
       - Call Compliance API
       - Evaluate all selected funds in parallel
       - Calculate capacity per fund
       - Determine overall status:
         * All Passed → Continue to allocation
         * Partial Failure → Wait for user approval
         * All Failed → Terminate with error

    3. USER INTERACTION (if partial failure)
       - Return compliance results to UI
       - User chooses to:
         * Proceed with compliant funds only
         * Cancel entire trade
         * Modify and resubmit

    4. ALLOCATION
       - Call Allocation API
       - Distribute amount across compliant funds
       - Apply selected methodology
       - Handle conflicts and shortfalls

    5. TRADE BOOKING
       - Call TradeBooking API
       - Persist trade and allocations
       - Generate confirmations
       - Create audit trail

    6. COMPLETION
       - Update orchestration state
       - Return final response
    */
}

// Rollback Strategy
public interface IRollbackHandler
{
    Task RollbackAsync(string requestId, RollbackReason reason);
}

public class RollbackHandler : IRollbackHandler
{
    private readonly ITradeBookingServiceClient _bookingClient;
    private readonly IOrchestrationStateRepository _stateRepository;
    private readonly ILogger<RollbackHandler> _logger;

    public async Task RollbackAsync(string requestId, RollbackReason reason)
    {
        var state = await _stateRepository.GetByIdAsync(requestId);

        if (state == null)
        {
            _logger.LogWarning(
                "Cannot rollback - state not found for request {RequestId}",
                requestId);
            return;
        }

        _logger.LogInformation(
            "Starting rollback for request {RequestId}, reason: {Reason}",
            requestId,
            reason);

        try
        {
            // Rollback in reverse order of execution
            if (state.BookingResult != null)
            {
                await RollbackBookingAsync(state.BookingResult);
            }

            // Allocation and Compliance are read-only operations,
            // no rollback needed

            state.Fail($"Rolled back due to {reason}");
            await _stateRepository.SaveAsync(state);

            _logger.LogInformation(
                "Rollback completed for request {RequestId}",
                requestId);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex,
                "Rollback failed for request {RequestId}",
                requestId);
            throw;
        }
    }

    private async Task RollbackBookingAsync(TradeBookingResponse bookingResult)
    {
        // Call TradeBooking API to cancel/void the trade
        await _bookingClient.CancelTradeAsync(bookingResult.TradeId);
    }
}

public enum RollbackReason
{
    UserCancelled,
    ValidationFailed,
    BookingFailed,
    Timeout,
    SystemError
}
