### 7.2 State Management

```csharp
// TradeOrchestrator.API/Domain/OrchestrationState.cs
public class OrchestrationState
{
    public string RequestId { get; private set; }
    public OrchestrationStatus Status { get; private set; }
    public string CurrentStep { get; private set; }

    public TradeSubmission Submission { get; private set; }
    public ComplianceResponse? ComplianceResult { get; private set; }
    public AllocationResponse? AllocationResult { get; private set; }
    public TradeBookingResponse? BookingResult { get; private set; }

    public DateTime CreatedAt { get; private set; }
    public DateTime UpdatedAt { get; private set; }
    public DateTime? CompletedAt { get; private set; }
    public string? ErrorMessage { get; private set; }

    public OrchestrationState(string requestId, TradeSubmission submission)
    {
        RequestId = requestId;
        Submission = submission;
        Status = OrchestrationStatus.Pending;
        CurrentStep = "Initiated";
        CreatedAt = DateTime.UtcNow;
        UpdatedAt = DateTime.UtcNow;
    }

    public void SetComplianceResult(ComplianceResponse result)
    {
        ComplianceResult = result;
        Status = result.OverallStatus switch
        {
            ComplianceStatus.AllPassed => OrchestrationStatus.Allocation,
            ComplianceStatus.PartialFailure => OrchestrationStatus.AwaitingApproval,
            ComplianceStatus.AllFailed => OrchestrationStatus.Failed,
            _ => Status
        };
        CurrentStep = "Compliance Completed";
        UpdatedAt = DateTime.UtcNow;
    }

    public void SetAllocationResult(AllocationResponse result)
    {
        AllocationResult = result;
        Status = OrchestrationStatus.Booking;
        CurrentStep = "Allocation Completed";
        UpdatedAt = DateTime.UtcNow;
    }

    public void SetBookingResult(TradeBookingResponse result)
    {
        BookingResult = result;
        CurrentStep = "Booking Completed";
        UpdatedAt = DateTime.UtcNow;
    }

    public void Complete()
    {
        Status = OrchestrationStatus.Completed;
        CurrentStep = "Completed";
        CompletedAt = DateTime.UtcNow;
        UpdatedAt = DateTime.UtcNow;
    }

    public void Fail(string errorMessage)
    {
        Status = OrchestrationStatus.Failed;
        ErrorMessage = errorMessage;
        CompletedAt = DateTime.UtcNow;
        UpdatedAt = DateTime.UtcNow;
    }
}
