public class CachedFundRepository : IFundRepository
{
    private readonly IFundRepository _innerRepository;
    private readonly IMemoryCache _cache;
    private readonly ILogger<CachedFundRepository> _logger;

    public async Task<Fund> GetByIdAsync(string id)
    {
        var cacheKey = $"fund:{id}";

        if (_cache.TryGetValue(cacheKey, out Fund cachedFund))
        {
            _logger.LogDebug("Cache hit for fund {FundId}", id);
            return cachedFund;
        }

        var fund = await _innerRepository.GetByIdAsync(id);

        if (fund != null)
        {
            _cache.Set(cacheKey, fund, CacheConfiguration.FundDataOptions);
            _logger.LogDebug("Cached fund {FundId}", id);
        }

        return fund;
    }

    public async Task<List<ComplianceRule>> GetActiveRulesAsync(
        string fundId, 
        DateTime effectiveDate)
    {
        var cacheKey = $"rules:{fundId}:{effectiveDate:yyyyMMdd}";

        if (_cache.TryGetValue(cacheKey, out List<ComplianceRule> cachedRules))
        {
            return cachedRules;
        }

        var rules = await _innerRepository.GetActiveRulesAsync(
            fundId, 
            effectiveDate);

        _cache.Set(cacheKey, rules, CacheConfiguration.ComplianceRulesOptions);

        return rules;
    }
}

// Distributed Cache for multi-instance deployment
public class DistributedCacheService
{
    private readonly IDistributedCache _cache;
    private readonly JsonSerializerOptions _jsonOptions;

    public async Task<T?> GetAsync<T>(string key)
    {
        var json = await _cache.GetStringAsync(key);

        if (string.IsNullOrEmpty(json))
            return default;

        return JsonSerializer.Deserialize<T>(json, _jsonOptions);
    }

    public async Task SetAsync<T>(
        string key, 
        T value, 
        TimeSpan expiration)
    {
        var json = JsonSerializer.Serialize(value, _jsonOptions);

        var options = new DistributedCacheEntryOptions
        {
            AbsoluteExpirationRelativeToNow = expiration
        };

        await _cache.SetStringAsync(key, json, options);
    }
}
