### 9.2 Transaction Management

```csharp
// TradeBooking.API/Services/TradeBookingService.cs
public class TradeBookingService : ITradeBookingService
{
    private readonly TradeDbContext _context;
    private readonly IAuditService _auditService;

    public async Task<TradeBookingResponse> BookAsync(
        TradeBookingRequest request)
    {
        using var transaction = await _context.Database.BeginTransactionAsync();

        try
        {
            // Create trade
            var trade = new Trade
            {
                Id = Guid.NewGuid(),
                SecurityId = request.Trade.SecurityId,
                CounterpartyId = request.Trade.CounterpartyId,
                TotalAmount = request.Trade.TotalAmount,
                Price = request.Trade.Price,
                TradeDate = request.Trade.TradeDate,
                SettlementDate = request.Trade.SettlementDate,
                Type = request.Trade.TradeType,
                Status = TradeStatus.Booked,
                CreatedBy = request.UserId,
                CreatedAt = DateTime.UtcNow
            };

            _context.Trades.Add(trade);

            // Create allocations
            var allocations = request.Allocations.Select(a => 
                new TradeAllocation
                {
                    Id = Guid.NewGuid(),
                    TradeId = trade.Id,
                    FundId = a.FundId,
                    AllocatedAmount = a.AllocatedAmount,
                    Shares = a.AllocatedShares,
                    PercentageOfTotal = a.PercentageOfTotal,
                    Status = AllocationStatus.Confirmed,
                    ConfirmationNumber = GenerateConfirmationNumber(),
                    CreatedAt = DateTime.UtcNow
                }
            ).ToList();

            _context.TradeAllocations.AddRange(allocations);

            // Create audit entries
            await _auditService.LogTradeCreatedAsync(trade, request.UserId);

            await _context.SaveChangesAsync();
            await transaction.CommitAsync();

            return new TradeBookingResponse(
                trade.Id.ToString(),
                trade.CreatedAt,
                allocations.Select(a => new AllocationConfirmation(
                    a.Id.ToString(),
                    a.FundId,
                    a.AllocatedAmount,
                    a.ConfirmationNumber
                )).ToList(),
                BookingStatus.Success
            );
        }
        catch (Exception ex)
        {
            await transaction.RollbackAsync();
            throw new BookingException("Trade booking failed", ex);
        }
    }
}
