### 9.3 Validation Approach

```csharp
// Shared/Validation/FluentValidation examples
public class TradeSubmissionValidator : AbstractValidator<TradeSubmission>
{
    public TradeSubmissionValidator(
        ISecurityRepository securityRepository,
        IFundRepository fundRepository)
    {
        RuleFor(x => x.SecurityId)
            .NotEmpty()
            .MustAsync(async (id, ct) => 
                await securityRepository.ExistsAsync(id))
            .WithMessage("Security does not exist");

        RuleFor(x => x.TotalAmount)
            .GreaterThan(0)
            .WithMessage("Trade amount must be positive");

        RuleFor(x => x.Price)
            .GreaterThan(0)
            .WithMessage("Price must be positive");

        RuleFor(x => x.TradeDate)
            .Must(date => date.Date <= DateTime.UtcNow.Date)
            .WithMessage("Trade date cannot be in the future");

        RuleFor(x => x.SelectedFunds)
            .NotEmpty()
            .WithMessage("At least one fund must be selected")
            .MustAsync(async (fundIds, ct) =>
            {
                var allExist = await Task.WhenAll(
                    fundIds.Select(id => fundRepository.ExistsAsync(id)));
                return allExist.All(exists => exists);
            })
            .WithMessage("One or more selected funds do not exist");

        RuleFor(x => x.AllocationMethodology)
            .IsInEnum()
            .WithMessage("Invalid allocation methodology");

        When(x => x.AllocationMethodology == AllocationMethodology.Custom,
            () =>
            {
                RuleFor(x => x.CustomRules)
                    .NotNull()
                    .WithMessage("Custom rules required for custom allocation");
            });
    }
}

public class ComplianceRequestValidator : AbstractValidator<ComplianceRequest>
{
    public ComplianceRequestValidator()
    {
        RuleFor(x => x.SecurityId)
            .NotEmpty();

        RuleFor(x => x.FundIds)
            .NotEmpty()
            .Must(funds => funds.Count <= 100)
            .WithMessage("Maximum 100 funds per evaluation");

        RuleFor(x => x.TotalAmount)
            .GreaterThan(0);
    }
}
