### 10.1 Dependency Injection Configuration

```csharp
// Each microservice's Startup.cs pattern
public class Startup
{
    public void ConfigureServices(IServiceCollection services)
    {
        // Database
        services.AddDbContext<ApplicationDbContext>(options =>
            options.UseSqlServer(
                Configuration.GetConnectionString("DefaultConnection"),
                sqlOptions =>
                {
                    sqlOptions.EnableRetryOnFailure(
                        maxRetryCount: 3,
                        maxRetryDelay: TimeSpan.FromSeconds(30),
                        errorNumbersToAdd: null);
                    sqlOptions.CommandTimeout(30);
                }));

        // Repository pattern
        services.AddScoped<IFundRepository, FundRepository>();
        services.AddScoped<IComplianceRuleRepository, ComplianceRuleRepository>();
        services.AddScoped<ITradeRepository, TradeRepository>();

        // Decorators for caching
        services.Decorate<IFundRepository, CachedFundRepository>();

        // Domain services
        services.AddScoped<IComplianceService, ComplianceService>();
        services.AddScoped<IAllocationService, AllocationService>();
        services.AddScoped<ITradeBookingService, TradeBookingService>();
        services.AddScoped<ITradeOrchestrationService, TradeOrchestrationService>();

        // Rule engine
        services.AddSingleton<IScriptEngine, RoslynScriptEngine>();
        services.AddScoped<IRuleEvaluator, RuleEvaluator>();

        // Allocation strategies
        services.AddTransient<ProRataAllocationStrategy>();
        services.AddTransient<TargetedAllocationStrategy>();
        services.AddTransient<CustomAllocationStrategy>();
        services.AddSingleton<IAllocationStrategyFactory, AllocationStrategyFactory>();

        // HTTP clients
        services.AddResilientHttpClient(
            "ComplianceClient",
            Configuration["Services:Compliance:BaseUrl"]);
        services.AddResilientHttpClient(
            "AllocationClient",
            Configuration["Services:Allocation:BaseUrl"]);
        services.AddResilientHttpClient(
            "TradeBookingClient",
            Configuration["Services:TradeBooking:BaseUrl"]);

        services.AddScoped<IComplianceServiceClient, ComplianceServiceClient>();
        services.AddScoped<IAllocationServiceClient, AllocationServiceClient>();
        services.AddScoped<ITradeBookingServiceClient, TradeBookingServiceClient>();

        // Caching
        services.AddMemoryCache();
        services.AddDistributedRedisCache(options =>
        {
            options.Configuration = Configuration["Redis:Connection"];
            options.InstanceName = "TradeAllocation:";
        });

        // Validation
        services.AddValidatorsFromAssemblyContaining<TradeSubmissionValidator>();
        services.AddFluentValidationAutoValidation();

        // Cross-cutting
        services.AddScoped<IAuditService, AuditService>();
        services.AddSingleton<IMetricsService, MetricsService>();

        // API
        services.AddControllers();
        services.AddEndpointsApiExplorer();
        services.AddSwaggerGen(c =>
        {
            c.SwaggerDoc("v1", new OpenApiInfo
            {
                Title = "Trade Allocation API",
                Version = "v1",
                Description = "Microservices for trade allocation and compliance"
            });
        });

        // Health checks
        services.AddHealthChecks()
            .AddDbContextCheck<ApplicationDbContext>()
            .AddRedis(Configuration["Redis:Connection"])
            .AddUrlGroup(
                new Uri(Configuration["Services:Compliance:BaseUrl"] + "/health"),
                "Compliance Service");
    }

    public void Configure(IApplicationBuilder app, IWebHostEnvironment env)
    {
        if (env.IsDevelopment())
        {
            app.UseDeveloperExceptionPage();
            app.UseSwagger();
            app.UseSwaggerUI();
        }

        app.UseExceptionHandler("/error");
        app.UseHttpsRedirection();
        app.UseRouting();
        app.UseAuthorization();

        app.UseEndpoints(endpoints =>
        {
            endpoints.MapControllers();
            endpoints.MapHealthChecks("/health");
        });
    }
}
